    h, w = len(grid), len(grid[0])
    full_rows = [(i, row[0]) for i, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    sep = max(set(v for _, v in full_rows), key=lambda c: sum(v == c for _, v in full_rows))
    rs = [i for i, row in enumerate(grid) if all(v == sep for v in row)]
    cs = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]
    r_bounds = [-1] + rs + [h]
    c_bounds = [-1] + cs + [w]
    r_spans = [(r_bounds[k] + 1, r_bounds[k+1]) for k in range(len(r_bounds)-1)]
    c_spans = [(c_bounds[k] + 1, c_bounds[k+1]) for k in range(len(c_bounds)-1)]
    rh, cw = r_spans[0][1] - r_spans[0][0], c_spans[0][1] - c_spans[0][0]
    template = None
    for tr, (r0, r1) in enumerate(r_spans):
        for tc, (c0, c1) in enumerate(c_spans):
            if tc == 0:
                continue
            mask = [[grid[r0+i][c0+j] != 0 for j in range(cw)] for i in range(rh)]
            if any(map(any, mask)):
                template = mask
                break
        if template is not None:
            break
    out = [[0 for _ in range(w)] for _ in range(h)]
    for i in rs:
        out[i] = [sep] * w
    for j in cs:
        for i in range(h):
            out[i][j] = sep
    for tr, (r0, r1) in enumerate(r_spans):
        marker = next((grid[r0+i][c_spans[0][0]+j] for i in range(rh) for j in range(cw) if grid[r0+i][c_spans[0][0]+j] != 0), 0)
        for c0, c1 in c_spans:
            for i in range(rh):
                for j in range(cw):
                    if template[i][j]:
                        out[r0+i][c0+j] = marker
    return out
